// Compare independent receiver estimates in their common plasma-line region.
use anyhow::{Result,ensure};use std::path::PathBuf;
fn main()->Result<()>{let root=PathBuf::from(std::env::args().nth(1).unwrap());let mut times=Vec::new();let mut correlations=Vec::new();let mut means=Vec::new();let mut peaks=Vec::new();
for i in 0..60{let t=1795564800+i*60;let dir=root.join(format!("minute-{t}/display"));if !dir.join("channel-overlap.h5").exists(){continue;}
 let f=hdf5::File::open(dir.join("channel-overlap.h5"))?;let rf=f.dataset("rf_frequency_hz")?.read_raw::<f64>()?;let r=hdf5::File::open(dir.join("profile-01-native.h5"))?.dataset("slant_range_km")?.read_raw::<f64>()?;let a=f.dataset("normalized_db_436")?.read_raw::<f32>()?;let b=f.dataset("normalized_db_444")?.read_raw::<f32>()?;ensure!(a.len()==b.len()&&a.len()==r.len()*rf.len(),"shape");
 let(mut n,mut sx,mut sy,mut sxx,mut syy,mut sxy)=(0.,0.,0.,0.,0.,0.);let mut max=[(-1e9,0.,0.);2];
 for(j,&range)in r.iter().enumerate(){if !(200. ..=300.).contains(&range){continue;}for(k,&freq)in rf.iter().enumerate(){if !(436.2e6..=437.5e6).contains(&freq){continue;}let ix=j*rf.len()+k;let x=a[ix]as f64;let y=b[ix]as f64;if x.is_finite()&&y.is_finite(){n+=1.;sx+=x;sy+=y;sxx+=x*x;syy+=y*y;sxy+=x*y;for(ch,v)in [x,y].into_iter().enumerate(){if v>max[ch].0{max[ch]=(v,range,freq);}}}}}
 ensure!(n>0.,"empty ROI");let corr=(sxy-sx*sy/n)/((sxx-sx*sx/n)*(syy-sy*sy/n)).sqrt();times.push(t as f64);correlations.push(corr);means.extend([sx/n,sy/n]);for p in max{peaks.extend([p.0,p.1,p.2]);}println!("OVERLAP {t}: correlation {corr:.3}; mean dB {:.3}/{:.3}; peaks {:?}",sx/n,sy/n,max);
}let n=times.len();ensure!(n>0,"no overlap products");let out=hdf5::File::create(root.join("overlap-summary.h5"))?;out.new_dataset::<f64>().shape(n).create("integration_start_utc_s")?.write_raw(&times)?;out.new_dataset::<f64>().shape(n).create("normalized_db_correlation")?.write_raw(&correlations)?;out.new_dataset::<f64>().shape((n,2)).create("region_mean_db")?.write_raw(&means)?;out.new_dataset::<f64>().shape((n,2,3)).create("peak_db_slant_range_km_rf_hz")?.write_raw(&peaks)?;for(name,v)in[("region_range_lower_km",200.),("region_range_upper_km",300.),("region_rf_lower_hz",436.2e6),("region_rf_upper_hz",437.5e6)]{out.new_attr::<f64>().create(name)?.write_scalar(&v)?;}Ok(())}
